// Read Register 100: Device Type
msg.payload = {
    fc: 3,           // Function Code 3 (Read Holding Registers)
    unitid: 1,       // Unit ID
    address: 100,    // Register 100
    quantity: 1      // Read 1 register
};
return msg;

// Parse Register 100 value
const data = msg.payload.data || msg.payload;
const value = data[0];

// Decode device type
let deviceType = 'Unknown';
let deviceTypeCode = value;

switch(value) {
    case 0x03:
    case 3:
        deviceType = 'Single Phase Hybrid';
        break;
    case 0x05:
    case 5:
        deviceType = 'Three Phase Hybrid';
        break;
    case 0x06:
    case 6:
        deviceType = 'Three Phase Inverter';
        break;
    default:
        deviceType = 'Unknown Type';
}

msg.payload = {
    register: 100,
    rawValue: value,
    hexValue: '0x' + value.toString(16).toUpperCase().padStart(2, '0'),
    deviceType: deviceType,
    deviceTypeCode: deviceTypeCode
};

node.status({
    fill: 'green',
    shape: 'dot',
    text: deviceType + ' (' + msg.payload.hexValue + ')'
});

return msg;
